import{_ as t,o as r,c as s,a6 as a}from"./chunks/framework.CCKCzdWs.js";const o="/diagrams/data-model-grid.svg",f=JSON.parse('{"title":"Core concepts","description":"The words a first Playwright run in Piwi meets: project, test run, test case, execution, baseline, failure cluster, and where each lives in the dashboard.","frontmatter":{"title":"Core concepts","description":"The words a first Playwright run in Piwi meets: project, test run, test case, execution, baseline, failure cluster, and where each lives in the dashboard.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/core-concepts.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/core-concepts.html"}],["meta",{"property":"og:title","content":"Core concepts | Piwi for Playwright"}],["meta",{"property":"og:description","content":"The words a first Playwright run in Piwi meets: project, test run, test case, execution, baseline, failure cluster, and where each lives in the dashboard."}]]},"headers":[],"relativePath":"guide/core-concepts.md","filePath":"guide/core-concepts.md","lastUpdated":1795266719000}'),i={name:"guide/core-concepts.md"};function n(c,e,l,d,h,u){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h1><p>Piwi reuses Playwright&#39;s vocabulary where it can, but a dashboard that keeps history needs a few distinctions Playwright doesn&#39;t have to make, most importantly between <em>a test</em> and <em>one run of that test</em>. This page names the dozen words a first run meets; the <a href="./concepts.html">Glossary</a> defines every word the docs and the dashboard use, each under the anchor other pages link.</p><h2 id="the-object-model" tabindex="-1">The object model <a class="header-anchor" href="#the-object-model" aria-label="Permalink to &quot;The object model&quot;">​</a></h2><figure><img src="'+o+'" alt="A project as a grid: test runs are columns, test cases are rows, and each cell holds that test case&#39;s executions in that run; one failure cluster spans failed executions of two test cases across two runs"><figcaption>A project holds one suite&#39;s results. A failure cluster groups executions, not test cases: it can span several of each.</figcaption></figure><p>Read it in two directions:</p><ul><li><strong>Down</strong>: &quot;what happened in this run?&quot; A run holds executions; each execution points at the test it is an attempt of.</li><li><strong>Across</strong>: &quot;how has this test behaved?&quot; A test case holds every execution of itself, in every run, over time. That&#39;s the axis flakiness, pass rate and duration trends are computed on.</li></ul><h2 id="the-words-a-first-run-meets" tabindex="-1">The words a first run meets <a class="header-anchor" href="#the-words-a-first-run-meets" aria-label="Permalink to &quot;The words a first run meets&quot;">​</a></h2><ul><li><strong><a href="./concepts.html#project">Project</a></strong>: one suite&#39;s results, created the first time results arrive under a new <code>projectName</code>.</li><li><strong><a href="./concepts.html#test-run">Test run</a></strong>: everything one <code>npx playwright test</code> invocation produced; one CI pipeline&#39;s shards make one run.</li><li><strong><a href="./concepts.html#test-case">Test case</a></strong>: a test&#39;s identity across time (file, <code>describe</code> path and title), the same on every browser. &quot;This test is flaky&quot; is about a test case.</li><li><strong><a href="./concepts.html#execution">Execution</a></strong>: one attempt of one test case, in one run, on one browser. A retry is an execution of its own.</li><li><strong><a href="./concepts.html#pass-rate">Pass rate</a></strong> and <strong><a href="./concepts.html#flaky-rate">flaky rate</a></strong>: the share of a test&#39;s results that passed, and that passed only on a retry.</li><li><strong><a href="./concepts.html#baseline-last-green-run">Baseline</a></strong>: the earlier run a run is compared with to answer &quot;what changed?&quot;, by default the last passing one.</li><li><strong><a href="./concepts.html#new-regression-newly-flaky">New regression, newly flaky</a></strong>: what a test did differently from the baseline.</li><li><strong><a href="./concepts.html#environment">Environment</a></strong>: a free-text label on a run (<code>staging</code>, <code>production</code>) that analysis can be narrowed to.</li><li><strong><a href="./concepts.html#error-fingerprint-failure-cluster">Failure cluster</a></strong>: the failed executions that share an error fingerprint, triaged once.</li><li><strong><a href="./concepts.html#cluster-state">Cluster state</a></strong>: where a cluster stands, in one sentence (<em>still failing</em>, <em>stopped failing</em>, <em>regressed</em>).</li><li><strong><a href="./concepts.html#flakiness-score">Flakiness score</a></strong>: how flaky a test is over its history, which ranks the flaky tests.</li><li><strong><a href="./concepts.html#tags-ownership">Tags &amp; ownership</a></strong>: the tags and the owner a test declares, which filter the views and route its failures.</li></ul><h2 id="where-each-concept-lives-in-the-ui" tabindex="-1">Where each concept lives in the UI <a class="header-anchor" href="#where-each-concept-lives-in-the-ui" aria-label="Permalink to &quot;Where each concept lives in the UI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>URL</th><th>Docs</th></tr></thead><tbody><tr><td>Project</td><td><code>/projects/:id</code></td><td><a href="/features/ui-overview.html#project-detail">UI overview</a></td></tr><tr><td>Test run</td><td><code>/test-runs/:id</code></td><td><a href="/features/ui-overview.html#test-run-detail">UI overview</a></td></tr><tr><td>Test case</td><td><code>/test-cases/:id</code></td><td><a href="/features/evidence.html#the-test-case-page">Failure evidence</a></td></tr><tr><td>Execution</td><td><code>/test-run-cases/:id</code></td><td><a href="/features/evidence.html#one-execution-diagnosis-first">Failure evidence</a></td></tr><tr><td>Failure cluster</td><td><code>/failure-clusters/:id</code></td><td><a href="/features/failure-clusters.html">Failure clusters</a></td></tr><tr><td>Cross-project view</td><td><code>/analytics</code></td><td><a href="/features/analytics.html">Analytics</a></td></tr><tr><td>Quality report</td><td><em>Quality report</em> on <code>/analytics</code> and <code>/projects/:id</code></td><td><a href="/features/quality-reports.html">Quality reports</a></td></tr><tr><td>Report schedule, report snapshot</td><td><code>/reports</code>, <code>/reports/:id</code></td><td><a href="/features/quality-reports.html#report-schedules">Quality reports</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./concepts.html">Glossary</a>: every word, with the page that holds its rule</li><li><a href="./getting-started.html">Getting started</a>: get results flowing in</li><li><a href="./first-failure.html">Your first failure, explained</a>: the words above on one failing test</li><li><a href="/features/ui-overview.html">UI overview</a>: a map of every page</li></ul>',12)])])}const m=t(i,[["render",n]]);export{f as __pageData,m as default};
